<?php require __DIR__.'/../bootstrap.php';require_login();$s=db()->prepare('SELECT p.*,COUNT(t.id) task_count,SUM(t.status="Completed") done FROM projects p LEFT JOIN tasks t ON t.project_id=p.id WHERE p.user_id=? GROUP BY p.id ORDER BY p.updated_at DESC');$s->execute([current_user()['id']]);$ps=$s->fetchAll();$title='Projects';require __DIR__.'/../includes/header.php';?><div class="page-head"><h1>Projects</h1><a class="btn" href="/projects/create/">+ New Project</a></div><div class="projects-grid"><?php foreach($ps as $p):$pct=$p['task_count']?round($p['done']/$p['task_count']*100):0;?><article class="card setting-target" id="project-<?=$p['id']?>"><span class="badge"><?=e($p['status'])?></span><h2><?=e($p['name'])?></h2><p><?=e($p['description'])?></p><div class="progress"><span style="width:<?=$pct?>%"></span></div><small><?=$pct?>% complete</small><a href="/projects/edit/?id=<?=$p['id']?>" class="edit-btn">Edit</a></article><?php endforeach;?></div><?php require __DIR__.'/../includes/footer.php'; ?>